CREATE TABLE public.purchase_order (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    purchase_order_id uuid NOT NULL,
    po_number character varying(255) NOT NULL,
    vendor_id uuid NOT NULL,
    status character varying(255) NOT NULL,
    version_number integer NOT NULL,
    currency character varying(255) NOT NULL,
    subtotal_minor bigint NOT NULL,
    tax_minor bigint NOT NULL,
    grand_total_minor bigint NOT NULL,
    open_balance_minor bigint,
    ship_to_location_id uuid,
    payment_terms_id character varying(255),
    po_date date,
    expected_delivery_date date,
    requested_by character varying(255),
    comment character varying(255),
    approver_id character varying(255),
    approval_timestamp timestamp(6) with time zone,
    approval_notes character varying(255),
    created_by character varying(255) NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_by character varying(255),
    updated_at timestamp(6) with time zone NOT NULL,
    supplier_ref character varying(100),
    transmission_state character varying(32) DEFAULT 'NOT_TRANSMITTED'::character varying NOT NULL,
    transmission_intent_id uuid,
    vendor_document_id character varying(255),
    supplier_order_number character varying(255),
    transmission_rejection_reason character varying(64),
    transmission_vendor_reason character varying(1024),
    transmission_requested_at timestamp(6) with time zone,
    transmission_observed_at timestamp(6) with time zone,
    transmission_count integer DEFAULT 0 NOT NULL,
    transmitted_version_number integer,
    CONSTRAINT purchase_order_status_check CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'APPROVED'::character varying, 'PARTIALLY_RECEIVED'::character varying, 'FULLY_RECEIVED'::character varying, 'CLOSED'::character varying, 'CANCELLED'::character varying])::text[])))
);

CREATE TABLE public.purchase_order_line (
