    version bigint DEFAULT 0 NOT NULL,
    order_number character varying(64),
    location_id uuid,
    label character varying(255),
    creation_idempotency_key character varying(128),
    customer_id uuid,
    vehicle_id uuid,
    customer_validation_status character varying(32),
    discount_total numeric(19,4) DEFAULT 0 NOT NULL,
    tax_total numeric(19,4) DEFAULT 0 NOT NULL,
    grand_total numeric(19,4) DEFAULT 0 NOT NULL,
    tax_stale boolean DEFAULT false NOT NULL,
    general_note character varying(2000),
    order_discount_type character varying(16),
    order_discount_value numeric(19,4),
    order_discount_reason_code character varying(64),
    quote_expires_at timestamp without time zone,
    invoice_id uuid,
    invoice_number character varying(64),
    checkout_idempotency_key character varying(128),
    amount_paid numeric(19,4) DEFAULT 0 NOT NULL,
    balance_due numeric(19,4),
    session_id uuid,
    deposit_source_type character varying(16),
    deposit_source_id uuid
);

CREATE TABLE public.sales_order_line (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    order_line_id uuid NOT NULL,
    order_id uuid NOT NULL,
    item_sku character varying(255) NOT NULL,
    item_description character varying(255) NOT NULL,
    quantity integer NOT NULL,
    unit_price numeric(19,4) NOT NULL,
    fulfillment_status character varying(255) NOT NULL,
    price_source character varying(255) NOT NULL,
    reason_code character varying(255),
    source_type character varying(255),
    source_id character varying(255),
    source_line_id character varying(255),
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    client_line_uuid uuid,
    discount_percent numeric(5,2),
    discount_amount numeric(19,4) DEFAULT 0 NOT NULL,
    line_subtotal numeric(19,4) DEFAULT 0 NOT NULL,
    tax_amount numeric(19,4) DEFAULT 0 NOT NULL,
    line_total numeric(19,4) DEFAULT 0 NOT NULL,
    customer_note character varying(1000),
    internal_note character varying(1000),
    pricing_breakdown text,
    returnable boolean,
    reservation_id uuid,
    backorder_id uuid
);

